if __name__ == '__main__':
    from PIL import Image, ImageDraw, ImageFont
    names = sorted(I); cols = 8; S = 6; cw = 150
    rows = (len(names) + cols - 1) // cols
    im = Image.new('RGB', (cols * cw, rows * 90), (16, 20, 25)); d = ImageDraw.Draw(im)
    for k, n in enumerate(names):
        x0, y0 = (k % cols) * cw + 50, (k // cols) * 90 + 10
        for r, row in enumerate(I[n]):
            assert len(row) == 9 and len(I[n]) == 9, n
            for c, ch in enumerate(row):
                if ch == '#': d.rectangle((x0 + c * S, y0 + r * S, x0 + c * S + S - 1, y0 + r * S + S - 1), fill=(139, 220, 255))
        d.text(((k % cols) * cw + 6, y0 + 60), n[:22], fill=(155, 168, 181))
    im.save('/tmp/icons.png'); print(len(names))
